/** /etc of a fake host (ADR-0117 decision 1): names, resolver, units, certificates, rotation. A fault changes the files it would change. */
import { certNames, pemText } from "./certs";
import type { TreeBuilder } from "./fs";
import { activeSpan, culpritName, type OsHost } from "./host";
import { DEAD_RESOLVER, NTP_SOURCE, portOf, RESOLVERS } from "./layout";

export function resolvConf(h: OsHost): string {
  const servers = activeSpan(h, "dns_failure") ? [DEAD_RESOLVER] : RESOLVERS;
  return [
    "# Generated by NetworkManager",
    "search dc.local",
    ...servers.map((s) => `nameserver ${s}`),
    "",
  ].join("\n");
}

function unitFile(h: OsHost, name: string): string {
  const app = h.services.some((s) => s.process === name);
  const interval = activeSpan(h, "process_crashloop")?.params.intervalS ?? 30;
  return [
    "[Unit]",
    `Description=${app ? (h.services.find((s) => s.process === name)?.name ?? name) : name}`,
    "After=network-online.target",
    "",
    "[Service]",
    "Type=simple",
    app ? "User=appsvc" : "User=root",
    `ExecStart=${app ? `/opt/app/bin/${name} --config /etc/${name}.conf` : `/usr/sbin/${name}`}`,
    "Restart=on-failure",
    `RestartSec=${Math.min(interval, 10)}s`,
    "LimitNOFILE=65536",
    "",
    "[Install]",
    "WantedBy=multi-user.target",
    "",
  ].join("\n");
}

/** The application's config; during a crash loop line 14 is the one it cannot read. */
function appConf(h: OsHost, name: string): string {
  const broken = activeSpan(h, "process_crashloop") !== undefined && name === culpritName(h);
  const lines = [
    `# ${name} configuration`,
    "[server]",
    `listen = 0.0.0.0:${portOf(name)}`,
    "workers = 8",
    "read_timeout = 30s",
    "write_timeout = 30s",
    "",
    "[storage]",
    `data_dir = /var/lib/${name}/data`,
    "fsync = true",
    "",
    "[limits]",
    "max_body = 8MiB",
    broken ? "max_conns = 1024 }" : "max_conns = 1024",
    "",
    "[tls]",
    `cert = /etc/ssl/certs/${name}.pem`,
    "[upstream]",
    "db = db.dc.local:5432",
    "",
  ];
  return lines.join("\n");
}

/** The rotation rule of an application; a disk that filled with old logs has its rotation switched off. */
function rotateConf(h: OsHost, name: string): string {
  const off = activeSpan(h, "disk_full") !== undefined;
  return [
    `/var/log/${name}/*.log {`,
    off ? "    # rotation disabled for maintenance (2026-10-10)" : "    daily",
    off ? "    #rotate 7" : "    rotate 7",
    ...(off ? [] : ["    compress"]),
    "    missingok",
    "    notifempty",
    "}",
    "",
  ].join("\n");
}

const PASSWD = [
  "root:x:0:0:root:/root:/bin/bash",
  "daemon:x:2:2:daemon:/sbin:/sbin/nologin",
  "chrony:x:994:992::/var/lib/chrony:/sbin/nologin",
  "syslog:x:993:991::/var/log/rsyslog:/sbin/nologin",
  "ops:x:1000:1000:ops:/home/ops:/bin/bash",
  "appsvc:x:1001:1001:application service:/var/lib/app:/sbin/nologin",
  "",
].join("\n");

const LOGROTATE = [
  '# see "man logrotate" for details',
  "weekly",
  "rotate 4",
  "create",
  "dateext",
  "include /etc/logrotate.d",
  "",
].join("\n");

const FSTAB = [
  "/dev/sda2  /          ext4  defaults,errors=remount-ro  1 1",
  "/dev/sda1  /boot      xfs   defaults                    0 0",
  "tmpfs      /dev/shm   tmpfs defaults,nosuid,nodev       0 0",
  "",
].join("\n");

export function buildEtc(b: TreeBuilder): void {
  const h = b.h;
  b.text("/etc/hostname", `${h.name}\n`);
  b.text(
    "/etc/hosts",
    `127.0.0.1 localhost localhost.localdomain\n${h.ip} ${h.name} ${h.name}.dc.local\n`,
  );
  b.file("/etc/resolv.conf", { content: () => resolvConf(h) });
  b.text(
    "/etc/os-release",
    'NAME="Red Hat Enterprise Linux"\nVERSION="9.4 (Plow)"\nID="rhel"\nVERSION_ID="9.4"\nPRETTY_NAME="Red Hat Enterprise Linux 9.4 (Plow)"\n',
  );
  b.text("/etc/fstab", FSTAB);
  b.text("/etc/passwd", PASSWD);
  b.text("/etc/group", "root:x:0:\nops:x:1000:\nappsvc:x:1001:\n");
  b.text("/etc/logrotate.conf", LOGROTATE);
  b.text(
    "/etc/chrony.conf",
    `server ${NTP_SOURCE} iburst\ndriftfile /var/lib/chrony/drift\nmakestep 1.0 3\nrtcsync\n`,
  );
  b.text("/etc/systemd/resolved.conf", `[Resolve]\nDNS=${RESOLVERS.join(" ")}\n`);
  b.text("/etc/localtime", "TZif2 UTC\n");
  b.dir("/etc/ssl/certs");
  for (const unit of h.os.processes.map((p) => p.name))
    b.file(`/etc/systemd/system/${unit}.service`, { content: () => unitFile(h, unit) });
  for (const s of h.services) {
    b.file(`/etc/${s.process}.conf`, { content: () => appConf(h, s.process) });
    b.file(`/etc/logrotate.d/${s.process}`, { content: () => rotateConf(h, s.process) });
  }
  for (const name of certNames(h))
    b.file(`/etc/ssl/certs/${name}.pem`, { content: () => pemText(h, name) });
}
